using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
namespace IonFrontier
{
    public sealed class IonTacticalTest : MonoBehaviour
    {
        [Serializable] public sealed class Report {public bool passed;public string[] checks,errors;public float averageFps;public int maxProjectiles,maxEnemies,maxWorld;}
        readonly List<string> checks=new List<string>(),errors=new List<string>();IonGame game;string destination;int frames,maxBolts,maxEnemies,maxWorld;float elapsed;
        void OnEnable(){Application.logMessageReceived+=Log;}
        void OnDisable(){Application.logMessageReceived-=Log;}
        void Log(string text,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)errors.Add(text);}
        void Update(){if(Time.unscaledDeltaTime>0){frames++;elapsed+=Time.unscaledDeltaTime;}if(game!=null){maxBolts=Mathf.Max(maxBolts,game.ActiveBullets);maxEnemies=Mathf.Max(maxEnemies,game.ActiveEnemies);maxWorld=Mathf.Max(maxWorld,game.ActiveWorldCount);}}
        void Begin(int stage=4){game.ReturnToMenu();game.SelectStage(stage);game.SelectHull(0);game.TestDraftSeed=11011;game.BeginRun();game.TestAutoDraft=false;game.TestInput=true;game.TestFire=false;game.TestFreezeEnemies=true;game.TestProtection(10000);game.TestTarget=game.PlayerPosition;game.TestHideBanner();}
        IEnumerator Start()
        {
            if(Array.IndexOf(Environment.GetCommandLineArgs(),"-ion-wait-focus")>=0)while(!Application.isFocused)yield return null;
            game=GetComponent<IonGame>();game.TestInput=true;game.TestFire=false;game.TestAutoDraft=false;var args=Environment.GetCommandLineArgs();int at=Array.IndexOf(args,"-ion-captures");destination=at>=0&&at+1<args.Length?args[at+1]:Application.persistentDataPath;Directory.CreateDirectory(destination);
            yield return new WaitForSecondsRealtime(.3f);Check(game.UnlockedStages==1&&!game.SessionUnlocked,"Tactical QA uses a separate fresh profile");game.TestSetProgress(13);Begin();yield return new WaitForSecondsRealtime(.08f);
            game.TestPrepareDraftWorld();game.TestGivePickup(PickupKind.Ultimate);game.UseUltimate();game.TestOpenDraft(0);
            Check(game.DraftActive&&game.DraftOpenCount==1,"A checkpoint enters upgrade-choice state");Check(game.DraftCardTitle(0)!=""&&game.DraftCardTitle(1)!=""&&game.DraftCardTitle(2)!=""&&game.DraftCardTitle(0)!=game.DraftCardTitle(1)&&game.DraftCardTitle(0)!=game.DraftCardTitle(2)&&game.DraftCardTitle(1)!=game.DraftCardTitle(2),"All three draft options are populated and distinct");
            string frozen=game.TestDraftSimulationSnapshot();game.TestTarget=new Vector2(5,-2);game.TestFire=true;game.TestDashRequest=true;yield return new WaitForSecondsRealtime(.4f);
            game.TestDraftSnapshotDifference(frozen);Check(game.TestDraftSimulationSnapshot()==frozen,"Draft freezes route, mission, bullets, enemies, world objects, loot, Q, dash, supply, targeting and backdrop clocks");Check(!game.UseUltimate(),"Draft rejects combat ultimate activation");yield return Capture("01-draft-16x9.png");game.TestFire=false;game.TestDashRequest=false;
            game.TogglePause();Check(game.State==FlightState.Paused&&game.DraftActive,"Pause preserves an unselected draft");yield return new WaitForSecondsRealtime(.2f);game.TogglePause();Check(game.DraftActive,"Resume returns to the pending draft");
            Check(game.ChooseUpgrade(0)&&!game.ChooseUpgrade(1)&&game.DraftChoicesMade==1,"A second click cannot award another card");game.TestResolveDraft();Check(game.State==FlightState.Playing,"Confirmed selection resumes combat");game.TestOpenDraft(0);Check(!game.DraftActive&&game.DraftOpenCount==1,"The same checkpoint cannot grant its reward twice");game.TestOpenDraft(1);Check(game.DraftOpenCount==2,"The second checkpoint has its own draft");
            Screen.SetResolution(1680,720,false);yield return new WaitForSecondsRealtime(.3f);yield return Capture("02-draft-21x9.png");Screen.SetResolution(1280,720,false);game.TestResolveDraft(2);game.ReturnToMenu();Check(!game.DraftActive&&game.ModuleCount==0,"Returning to hangar clears draft and module state");
            Begin();Check(game.DraftOpenCount==0&&game.DraftChoicesMade==0&&game.ModuleCount==0,"Replay resets checkpoint consumption and modules");
            for(int i=0;i<9;i++){Begin(1);Check(game.TestModuleEffect(i),"Module "+((CombatModule)i)+" changes actual firing, collision, damage or pickup behavior");}
            string[] sourceChecks={"Secondary friendly collision kills cannot trigger aftershock or ammo refunds","Blocked elite body hits cannot trigger fragments or hit-count arcs","A maximum multishot piercing fan creates at most four fragments per volley","Several projectiles in one volley count only once towards seeking lightning","In-flight bolts retain module eligibility from firing despite later pattern replacement","A full projectile pool rejects firing without spending ammo or module charges","Fragments inherit the struck engine exclusion mask","Kills before obtaining a module do not advance its refund counter"};
            for(int i=0;i<sourceChecks.Length;i++){Begin(i==1||i==6?4:1);Check(game.TestModuleSourceSafety(i),sourceChecks[i]);}
            Begin(1);Check(game.TestGrantModule(CombatModule.PulseChamber)&&game.TestGrantModule(CombatModule.DashCapacitor)&&!game.TestGrantModule(CombatModule.SalvageMagnet)&&game.ModuleCount==2,"Module slots enforce the two-module cap");
            Begin(1);game.TestGivePickup(PickupKind.Spread);game.TestGrantModule(CombatModule.FocusedSpread);game.TestGivePickup(PickupKind.Pierce);game.TestGivePickup(PickupKind.Homing);Check(game.HasModule(CombatModule.FocusedSpread)&&!game.ModuleActive(CombatModule.FocusedSpread),"Replacing a prerequisite pattern suspends its module without deleting it");game.TestGivePickup(PickupKind.Spread);Check(game.ModuleActive(CombatModule.FocusedSpread),"Reacquiring the prerequisite reactivates the module");
            Begin(1);game.TestPrepareMaxDraft();game.TestOpenDraft(0);Check(game.DraftActive&&game.TestDraftCardsValid(),"A fully capped loadout still receives valid fallback cards");game.TestResolveDraft();
            Begin(1);game.TestPrepareModuleCombo();game.TestFire=true;yield return new WaitForSecondsRealtime(.8f);yield return Capture("02a-module-combo.png");game.TestFire=false;Check(game.State==FlightState.Playing&&game.ActiveBullets>0&&game.ActiveBullets<512&&game.ModuleFragmentsCreated>0&&game.ModuleCount==2&&game.Loadout.ShotCount==15,"Maximum spread/pierce multishot with two modules stays within the projectile pool");
            for(int type=0;type<6;type++)
            {
                Begin(6);game.TestStartEncounter(type);game.TestAdvanceEncounter(2);Check(game.EncounterActive&&game.EncounterTypeIndex==type&&game.EncounterMembersAlive>=2,"Coordinated encounter "+type+" owns real live ships");
                if(type==0){Check(game.EncounterShieldLinks>0&&game.TestEncounterLinksVisible&&Mathf.Abs(game.TestEncounterDamageRatio()-.65f)<.02f,"Shield leader reduces actual ally damage by thirty-five percent with visible links");yield return Capture("03-shield-lance.png");game.TestKillEncounterRole(0);Check(Mathf.Abs(game.TestEncounterDamageRatio()-1)<.02f,"Killing shield leader immediately restores full damage");Check(game.TestEncounterReusedSlotSafe(),"Reused enemy slots cannot inherit an old formation role");}
                if(type==1){game.TestAdvanceEncounter(2.3f);Check(game.EncounterPullEvents>0&&game.EncounterLaserEvents>0,"Tractor formation warns, pulls and fires its coordinated laser");yield return Capture("04-tractor-crossfire.png");game.TestKillEncounterRole(0);int pulls=game.EncounterPullEvents;game.TestAdvanceEncounter(8);Check(game.EncounterPullEvents==pulls,"Destroyed tractor stops later pull cycles");}
                if(type==2){game.TestSetEncounterCarrierHealth(1);game.TestAdvanceEncounter(5.2f);Check(game.TestEncounterCarrierHealth>1&&game.EncounterHealPulses>0&&game.EncounterChildCount>0&&game.EncounterChildCount<=4,"Workshop repairs its carrier and spawns a capped child fleet");game.TestKillEncounterRole(1);int heals=game.EncounterHealPulses;game.TestKillEncounterRole(0);int children=game.EncounterChildrenSpawned;game.TestAdvanceEncounter(6);Check(game.EncounterHealPulses==heals&&game.EncounterChildrenSpawned==children&&game.EncounterChildCount<=4,"Mechanic death stops healing and carrier death stops additional children");}
                if(type==3){game.TestAdvanceEncounter(6);Check(game.EncounterFireEvents>0,"Pincer wings execute attack passes with live projectiles");yield return Capture("05-pincer-wings.png");}
                if(type==4){game.TestKillEncounterRole(0);int rewards=game.EncounterAlarmRewards;game.TestAdvanceEncounter(9);Check(rewards==1&&game.EncounterAlarmRewards==1&&game.EncounterAlarmCalls==0,"Early alarm kill rewards once and prevents reinforcements");game.TestStartEncounter(4);game.TestAdvanceEncounter(10);Check(game.EncounterAlarmCalls==1&&game.EncounterChildCount>0,"An ignored alarm calls reinforcements exactly once");}
                if(type==5){game.TestAdvanceEncounter(6);Check(game.EncounterMineEvents>0&&game.EncounterTorpedoes>0,"Mine layer and torpedo ship deploy actual hazards");}
                Check(game.ActiveEnemies<=18&&game.ActiveBullets<512,"Encounter "+type+" respects fixed pool budgets");game.TestClearEncounter();Check(!game.EncounterActive&&!game.TestEncounterLinksVisible,"Encounter "+type+" cleanup removes active links");
            }
            Begin();game.TestAutoDraft=true;game.TestCounterBegin();yield return Capture("06a-counter-two-engines.png");float body=game.CounterBodyHealth;game.TestCounterDamageBody(1000);Check(game.CounterBodyHealth==body&&!game.BossActive,"Elite body shield blocks damage and never starts a boss fight");game.TestCounterShootEngine(0);yield return new WaitForSecondsRealtime(.2f);Check(game.CounterLeftHealth<18,"A real friendly bolt hits an engine weak point");game.TestCounterDamageEngine(0,1000);Check(game.CounterEnginesAlive==1&&game.CounterLeftHealth==0,"Destroying one engine disables that weakpoint");yield return Capture("06-counter-one-engine.png");
            game.TestGivePickup(PickupKind.Ultimate);game.UseUltimate();Check(game.CounterEnginesAlive==0,"The hull ultimate can destroy the remaining engine");int score=game.Score,ammo=game.Ammo;game.TestCounterDamageBody(1000);Check(game.CounterSucceeded&&game.CounterWreckActive&&game.Score==score+600&&game.Ammo==Mathf.Min(600,ammo+40)&&game.State==FlightState.Playing&&!game.BossActive,"Exposed body kill gives the optional reward and a separate elite wreck");yield return new WaitForSecondsRealtime(1.4f);yield return Capture("07-counter-wreck.png");yield return new WaitForSecondsRealtime(1.5f);game.ReturnToMenu();Check(game.TestCounterAllClean,"Menu removes elite wreck, weakpoints, warnings and inspected target");
            Begin();game.TestAutoDraft=true;game.TestCounterBegin();game.TestGivePickup(PickupKind.Ultimate);string progress=game.TestTacticalProgressSnapshot();int qScore=game.Score;game.UseUltimate();yield return new WaitForSecondsRealtime(1.9f);
            Check(game.CounterSucceeded&&game.Score==qScore+600&&game.State==FlightState.Playing&&!game.BossActive&&game.BossCombatSeconds==0&&game.TestTacticalProgressSnapshot()==progress,"A real Ion ultimate destroys both engines and the elite without early progression, stars or boss time");
            Begin();game.TestAutoDraft=true;game.TestFreezeEnemies=false;game.TestCounterBegin();game.TestPrepareUnupgradedCounterTrial();game.TestSetAmmo(300);game.TestFire=true;float deadline=Time.realtimeSinceStartup+14;while(game.CounterActive&&Time.realtimeSinceStartup<deadline){game.TestTarget=game.CounterIonAim;yield return null;}game.TestFire=false;
            Check(game.CounterSucceeded&&game.AmmoSpent>0&&!game.BossActive&&game.Gun==GunKind.Ion&&game.Loadout.PatternCount==0&&game.Loadout.DamageStacks==0&&game.Loadout.RateStacks==0&&game.Loadout.MultishotStacks==0&&game.ModuleCount==0,"Unupgraded starter Ion gun can naturally kill both engines and the body inside the optional window");yield return Capture("08-counter-ion-success.png");
            Begin();game.TestAutoDraft=true;game.TestCounterBegin();game.TestCounterRetreat();Check(game.CounterExpired&&!game.CounterSucceeded&&game.State==FlightState.Playing&&!game.BossActive,"Skipping the optional kill withdraws the elite without defeat or early victory");yield return Capture("09-counter-timeout.png");game.TestEscapeAdvanceTo(3590);game.TestFreezeEnemies=false;deadline=Time.realtimeSinceStartup+3;while(!game.BossActive&&Time.realtimeSinceStartup<deadline)yield return null;Check(game.BossActive&&game.EscapeFraction==1,"The route still ends at the normal final boss after an elite timeout");game.ReturnToMenu();Check(game.TestCounterAllClean,"Boss-transition cleanup leaves no elite warnings or weakpoints");
            var report=new Report{passed=errors.Count==0,checks=checks.ToArray(),errors=errors.ToArray(),averageFps=elapsed>0?frames/elapsed:0,maxProjectiles=maxBolts,maxEnemies=maxEnemies,maxWorld=maxWorld};File.WriteAllText(Path.Combine(destination,"tactical-report.json"),JsonUtility.ToJson(report,true));Debug.Log("ION_TACTICAL_TEST_"+(report.passed?"PASS":"FAIL"));yield return new WaitForSecondsRealtime(.2f);Application.Quit(report.passed?0:1);
        }
        IEnumerator Capture(string name){yield return null;yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(destination,name));yield return new WaitForSecondsRealtime(.12f);}
        void Check(bool pass,string text){checks.Add((pass?"PASS: ":"FAIL: ")+text);if(!pass){errors.Add(text);Debug.LogWarning("TACTICAL_FAIL: "+text);}}
    }
}
